import { handleMetadataMerge, handleCompanyCommentDataMerge } from "@/entrypoints/offscreen/worker/service/app/taskMerge";
import { expect, test, vi } from "vitest";
import { parse,dateToStr } from "@/common/utils/date";
import * as modTaskDataMergeService from "@/entrypoints/offscreen/worker/service/taskDataMergeService";
import * as modFileService from "@/entrypoints/offscreen/worker/service/fileService";
import { TASK_TYPE_COMPANY_COMMENT_DATA_MERGE } from "@/common";
import { getDb } from "@/entrypoints/offscreen/worker/database";
import { PGlite } from "@electric-sql/pglite";
import { SERVICE_INSTANCE as TASK_DATA_MERGE_SERVICE_INSTANCE } from "@/entrypoints/offscreen/worker/service/taskDataMergeService";
import { SERVICE_INSTANCE as COMPANY_COMMENT_SERVICE_INSTANCE } from "@/entrypoints/offscreen/worker/service/companyCommentService";

test('handleCompanyCommentDataMerge in correct logic', async () => {
  const db = await getDb({ dataDir: 'memory://' });
  expect(db).toBeInstanceOf(PGlite);
  const taskDataMergeId = `3479efa1-43ea-4de4-adbf-c71b1958c852`;
  vi.spyOn(modTaskDataMergeService, '_taskDataMergeGetById').mockImplementation(({ param }) => {
    expect(param).toBe(taskDataMergeId);
    return {
      id: "3479efa1-43ea-4de4-adbf-c71b1958c852",
      type: TASK_TYPE_COMPANY_COMMENT_DATA_MERGE,
      username: "lastsunday",
      reponame: "job-hunting-data-source",
      datetime: parse('2025-05-29'),
      typeId: null,
      dataId: "8b60548d-2eb9-4383-95ee-726a2e300a4c",
      config: { "name": "深圳避雷公司名单", "type": "COMPANY_COMMENT_DATA_DOWNLOAD", "emotion": "NEGATIVE", "fileName": "mine_field_shenzhen", "description": "来自网络收集", "retentionDay": 3650 },
      dataCount: 893,
      dataPageNum:1,
      dataPageSize:10000, 
      createDatetime: parse("2025-05-29"),
      updateDatetime: parse("2025-05-29"),
    }
  });
  vi.spyOn(modFileService, '_fileGetById').mockImplementation(async ({ param }) => {
    expect(param).toBe("8b60548d-2eb9-4383-95ee-726a2e300a4c");
    return {
      id: `8b60548d-2eb9-4383-95ee-726a2e300a4c`,
      name: `mine_field_shenzhen.zip`,
      content: "",
    };
  });
  const result = await handleCompanyCommentDataMerge({ dataId: taskDataMergeId });
  expect(result).toBeUndefined();
  const taskDataMerge = await TASK_DATA_MERGE_SERVICE_INSTANCE._getById(taskDataMergeId);
  expect(taskDataMerge.dataCount).toBe(893);
  const searchResult = await COMPANY_COMMENT_SERVICE_INSTANCE._search({});
  expect(searchResult.total).toBe(916);
  expect(dateToStr(parse(searchResult.items[0].createDatetime))).toBe(dateToStr(parse('2025-05-29')));
});
